    "usd-demsn": {"status":"unreachable","last_verified":"2026-11-24","notes":"University of San Diego's website could not be read on 2026-11-24 (the MEPN admissions and timeline pages returned no readable content; GPA, grade and recency figures were seen only in search-result excerpts). Admissions details are not recorded yet: check with the school."},
    "usf-demsn": {"prerequisites":[{"course":"Human Anatomy (4 credits, lecture and lab)","code":null,"category":"anatomy","min_grade":"C","within_years":5,"by_when":"apply","one_of":null},{"course":"Physiology (4 credits, lecture and lab)","code":null,"category":"physiology","min_grade":"C","within_years":5,"by_when":"apply","one_of":null},{"course":"Microbiology (4 credits, lecture and lab)","code":null,"category":"micro","min_grade":"C","within_years":5,"by_when":"apply","one_of":null},{"course":"One psychology course","code":null,"category":"psych","min_grade":"C","within_years":"not_published","by_when":"apply","one_of":null},{"course":"College composition (part of 6 semester / 9 quarter credits in communication)","code":null,"category":"eng1","min_grade":"C","within_years":"not_published","by_when":"apply","one_of":null},{"course":"Additional communication credits to total 6 semester / 9 quarter credits","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"apply","one_of":null},{"course":"One statistics course","code":null,"category":"stats","min_grade":"C","within_years":"not_published","by_when":"apply","one_of":null},{"course":"16 semester / 24 quarter credits in natural, behavioral, or social sciences","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"apply","one_of":null}],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"none","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"Prerequisites must be completed with a \"C\" or higher by the application deadline. In-progress prerequisite courses will not be accepted. Each lab science prerequisite must be 4 units or greater, completed within five (5) years of the application term.","gpa":"ME-MSN applicants must have a Bachelor's institution GPA above 2.75 in order to be considered for admissions. A preferred Bachelor's institution GPA of 3.0 or above.","exam":"TEAS or GRE: not required (admission page).","selection":"Holistic review; no interviews; personal statement reviewed by the committee.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://www.usfca.edu/nursing/programs/graduate/masters-nursing/admission/me-msn","https://www.usfca.edu/nursing/programs/graduate/masters-nursing/admission","https://www.usfca.edu/nursing/programs/graduate/masters/msn/program-overview/me-msn","https://www.usfca.edu/nursing/admission-aid/application-deadlines"],"last_verified":"2026-11-24","academic_year":"Fall 2027 admission","deadline":"San Francisco: Fall 2027 apply by February 1 (11:59 PM PST); Spring deadline September 1 (Spring 2027 deadline has passed). Orange County applications paused until further notice.","notes":"Requires a bachelor's degree in a field outside nursing. The general master's admission page says prerequisites must be complete before the start of the semester, but the ME-MSN admission page says in-progress prerequisites are not accepted and courses must be completed by the application deadline - follow the stricter rule. Online courses with virtual labs accepted; CLEP not accepted; AP only with college credit. Two letters of recommendation. No deferrals. Orange County option paused."},
    "samuel-merritt-demsn": {"prerequisites":[{"course":"English Composition","code":null,"category":"eng1","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"English Literature/Critical Thinking","code":null,"category":"eng2","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Communication or Speech elective","code":null,"category":"speech","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Introduction to Sociology or Cultural Anthropology","code":null,"category":"soc","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Social Science elective","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Life Span Developmental Psychology (birth to death)","code":null,"category":"lifespan","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Nutrition","code":null,"category":"nutrition","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Statistics","code":null,"category":"stats","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Human Anatomy with Lab (4 units)","code":null,"category":"anatomy","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Human Physiology with Lab (4 units)","code":null,"category":"physiology","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Chemistry with Lab (4 semester/6 quarter units)","code":null,"category":"chem","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Microbiology with Lab (4 units)","code":null,"category":"micro","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null}],"rules":{"gpa_overall_min":"not_published","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":{"name":"HESI A2 or TEAS","min_overall":"not_published","min_sections":"Recommended (not stated as minimum): HESI A2 75% or higher in each subject area, or TEAS 65% or higher in each subject area (TEAS starting Spring 2027)","max_attempts":"not_published","valid_months":"not_published"},"selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"\"Prerequisites must be completed before the beginning of the program AND completed with a grade of C or better.\" In-progress courses OK at application; \"It is not possible to complete any prerequisites concurrently with the ELMSN program.\"","gpa":"\"Recommended minimum 3.0 GPA on the last 60 semester/90 quarter units of coursework.\" \"Recommended minimum 3.0 GPA in the four science prerequisite courses.\"","exam":"Recommended HESI A2 score of 75% or higher in each subject area, or TEAS 65% or higher in each subject area (starting Spring 2027). ELMSN-PMHNP page: starting Spring 2027 the program will require a completed TEAS or HESI score.","selection":"\"Selection for admission is an administrative decision based on a comprehensive assessment of likelihood of success.\" Short-answer responses; conversational skill in a second language \"highly desirable.\"","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://www.samuelmerritt.edu/entry-level-master-science-nursing-family-nurse-practitioner","https://www.samuelmerritt.edu/entry-level-master-science-nursing-psychiatric-mental-health-family-nurse-practitioner","https://www.samuelmerritt.edu/2026-2027/admission-policies"],"last_verified":"2026-11-24","academic_year":"Spring 2027 admission","deadline":"Spring 2027 (Sacramento): standard deadline Dec 1, 2026; classes begin Jan 11, 2027","notes":"Requires a bachelor's degree from a regionally accredited institution. Completes pre-licensure first (BSN-equivalency letter on request; no BSN awarded), then the FNP or PMHNP graduate phase; both tracks take about 39 months. ELMSN-PMHNP students admitted for Spring 2027 receive a $15,000 scholarship. NursingCAS fee stated as $80 on the ELMSN page."},
