    "ucsf-cnm": {"prerequisites":[],"rules":{"gpa_overall_min":3,"gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"none","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"\"Beginning with applications for fall 2027, completion of a statistics course is no longer required.\" Requires a bachelor's degree in nursing or an MSN from an accredited institution.","gpa":"\"All applicants are required to demonstrate a minimum GPA of 3.0.\"","exam":"\"No GRE is required.\"","selection":"Once complete, the specialty and DNP faculty review the application and decide to offer admission, deny admission, or waitlist the applicant.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://nursing.ucsf.edu/programs/doctoral-programs/bsn-entry-dnp-advanced-nursing-focus/bsn-entry-dnp-application","https://nursing.ucsf.edu/programs/doctoral-programs/bsn-entry-dnp-advanced-nursing-focus/bsn-entry-dnp-process-and-deadlines","https://nursing.ucsf.edu/bsn-entry-dnp-advanced-nursing-focus"],"last_verified":"2026-11-24","academic_year":"Fall 2027 admission","deadline":"Fall 2027: applications open Sept 15, 2026; apply by Feb 14, 2027 (decisions March-April 2027)","notes":"Requires a BSN or MSN from an accredited program and a California RN license (\"Applicants must be licensed as a Registered Nurse (RN) in California\"). No GRE. Hybrid, mostly online 11-quarter program; F-1 visa applicants cannot meet the in-person requirement."},
