    "uc-davis-fnp": {"prerequisites":[{"course":"Human Anatomy with lab","code":null,"category":"anatomy","min_grade":"C","within_years":"see_text","by_when":"not_published","one_of":"g1"},{"course":"Human Physiology with lab","code":null,"category":"physiology","min_grade":"C","within_years":"see_text","by_when":"not_published","one_of":"g1"},{"course":"Anatomy & Physiology I with lab (series alternative)","code":null,"category":"ap1","min_grade":"C","within_years":"see_text","by_when":"not_published","one_of":"g2"},{"course":"Anatomy & Physiology II with lab (series alternative)","code":null,"category":"ap2","min_grade":"C","within_years":"see_text","by_when":"not_published","one_of":"g2"},{"course":"Organic or Biochemistry with lab","code":null,"category":"chem_ob","min_grade":"C","within_years":"not_published","by_when":"not_published","one_of":null},{"course":"Microbiology or Bacteriology with lab","code":null,"category":"micro","min_grade":"C","within_years":"not_published","by_when":"not_published","one_of":null},{"course":"English composition","code":null,"category":"eng1","min_grade":"C","within_years":"not_published","by_when":"not_published","one_of":null},{"course":"Social science course (1 of 2)","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"not_published","one_of":null},{"course":"Social science course (2 of 2)","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"not_published","one_of":null}],"rules":{"gpa_overall_min":3,"gpa_prereq_min":"not_published","gpa_science_min":3,"exam":"not_published","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"Each course at least three units, grade of C or better. Anatomy and physiology ideally \"completed within the past five years of when you plan to apply.\" BSN or entry-level prelicensure master's holders may have all prerequisites waived; ADN holders with a non-nursing bachelor's must complete all.","gpa":"\"A minimum bachelor's degree GPA of 3.0\"; \"A minimum cumulative 3.0 GPA in all science prerequisite coursework is required\".","exam":null,"selection":"Decisions are made case by case and admission is competitive; meeting criteria establishes eligibility, not admission. Interview may be required.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://health.ucdavis.edu/nursing/admissions/programs/DNP-FNP.html","https://health.ucdavis.edu/nursing/academics/programs/dnp-fnp.html"],"last_verified":"2026-11-24","academic_year":"Summer 2027 admission","deadline":"Summer 2027: applications opened late September; guaranteed-consideration deadline Jan 5, 2027 (11:59 p.m. PT); applications Jan 5 - June 1, 2027 reviewed only if space remains","notes":"Requires a current unencumbered RN license and a bachelor's degree (any major). Prerequisites are waived for BSN/entry-level master's holders, so most BSN-prepared applicants need none. GRE/MCAT not mentioned on the admissions page."},
    "uc-davis-crna": {"prerequisites":[],"rules":{"gpa_overall_min":3,"gpa_prereq_min":"not_published","gpa_science_min":"see_text","exam":"not_published","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"Prerequisites (A&P with lab, organic chemistry or biochemistry with lab, microbiology with lab, two social sciences, English composition; C or better) are waived for applicants with a BSN or MSN from an accredited university.","gpa":"Minimum cumulative bachelor's GPA of 3.0; minimum 3.0 in science prerequisites, required only for applicants without a BSN or MSN.","exam":null,"selection":"NursingCAS application; a select pool is invited to apply through UC Davis Graduate Studies; interview may be required. Admission is competitive and decided case by case.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://health.ucdavis.edu/nursing/admissions/programs/DNP-NA.html","https://health.ucdavis.edu/nursing/academics/programs/dnp-nurse-anesthesia.html"],"last_verified":"2026-11-24","academic_year":"Summer 2027 admission","deadline":"Summer 2027: applications opened Aug 6, 2026 and closed Nov 1, 2026 (11:59 p.m. ET), now passed; next cycle dates not yet posted","notes":"Requires a BSN or MSN (prerequisites waived for these), a current unencumbered US RN/APRN license plus California licensure eligibility before matriculation, at least one year full-time (or part-time equivalent, 2,080 hours) acute critical care RN experience (strongly preferred by application, required by matriculation), and at least 8 hours shadowing a CRNA or physician anesthesiologist before applying. GRE and CCRN are not mentioned."},
