    "fresno-pacific-fnp": {"prerequisites":[{"course":"College-level statistics","code":null,"category":"stats","min_grade":"not_published","within_years":"not_published","by_when":"apply","one_of":null},{"course":"Chemistry (with lab)","code":null,"category":"chem","min_grade":"not_published","within_years":"not_published","by_when":"apply","one_of":null},{"course":"Upper-division writing","code":null,"category":"other","min_grade":"not_published","within_years":"not_published","by_when":"apply","one_of":null}],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"not_published","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"Transcripts must show \"college-level statistics, chemistry (with lab), and upper-division writing courses.\"","gpa":"\"If your cumulative GPA for your bachelor's degree is below a 3.0 (4.0 scale), a letter of explanation is required.\"","exam":null,"selection":"Admission is \"based on a review of each applicant's complete profile\" (academic record, work experience, references, personal statement, interview).","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://www.fresno.edu/graduate/program/nursing-msnfnp"],"last_verified":"2026-11-25","academic_year":"Fall 2027 admission","deadline":"Fall: June 1 (Fall 2027: June 1, 2027); Spring: November 15 (Nov 15, 2026 has passed); late applications considered on a space-available basis","notes":"BSN from an accredited program; California RN license; resume with work experience (no minimum stated); two references from the medical field; statement of intent; interview. Background check, physical/immunizations and malpractice insurance due by the end of the first semester. GRE not mentioned."},
    "saint-marys-ca-bsn": {"prerequisites":[{"course":"Chemistry with lab","code":"CHEM 105+L or CHEM 110+L","category":"chem","min_grade":"C-","within_years":"not_published","by_when":"start","one_of":null},{"course":"Statistics","code":"MATH 104 or DATA 105","category":"stats","min_grade":"C-","within_years":"not_published","by_when":"start","one_of":null},{"course":"Psychology","code":"PSYCH 100","category":"psych","min_grade":"C-","within_years":"not_published","by_when":"start","one_of":null},{"course":"Nutrition","code":"HS 331, KINES 361 or HS 121","category":"nutrition","min_grade":"C-","within_years":"not_published","by_when":"start","one_of":null},{"course":"Sociology","code":"SOC 204 (or another sociology course)","category":"soc","min_grade":"C-","within_years":"not_published","by_when":"start","one_of":null},{"course":"Writing","code":"WRIT 100 or 101","category":"eng1","min_grade":"C","within_years":"not_published","by_when":"start","one_of":null},{"course":"Anatomy & Physiology with lab, first course of two-semester sequence","code":"BIOL 215+L or BIOL 250+L","category":"ap1","min_grade":"B-","within_years":7,"by_when":"start","one_of":null},{"course":"Anatomy & Physiology with lab, second course of two-semester sequence","code":"BIOL 225+L or BIOL 251+L","category":"ap2","min_grade":"B-","within_years":7,"by_when":"start","one_of":null},{"course":"Microbiology with lab","code":"BIOL 317+L or BIOL 140+L","category":"micro","min_grade":"B-","within_years":7,"by_when":"start","one_of":null}],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":2.8,"gpa_science_min":2.8,"exam":{"name":"TEAS","min_overall":"see_text","min_sections":"not_published","max_attempts":"see_text","valid_months":"not_published"},"selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"\"Chemistry, Statistics, Psychology, Nutrition, & Sociology (C- or higher)\"; \"Writing (C or higher)\"; \"Anatomy, Physiology, and Microbiology (within 7 years and a B- or higher)\"; A&P \"BIOL 215+L AND 225+L, OR BIOL 250+L AND 251+L (two-semester sequence)\". \"It is permissible for students to apply for the program with some program prerequisites in progress.\"","gpa":"\"Students must complete all nursing prerequisite coursework with a 2.8 GPA or higher overall GPA\"; \"2.8 or higher GPA in required science courses (Microbiology, Anatomy, Physiology, Nutrition, Sociology, and Psychology)\".","exam":"Admissions pages list \"TEAS Exam Results\" with no minimum. Handbook documents (Feb 2025): \"Teas Score 70% or higher, or a petition for consideration\"; \"ATI-TEAS Test with 70% or higher within 2 attempts\"; below 70% may apply with a letter requesting consideration.","selection":"Unofficial transcripts, two letters of recommendation, resume, TEAS results and \"Interview with the Nursing Admissions Team.\" Handbook: holistic review; \"Admission is not solely on academic standing.\" Transfer \"acceptance is subject to space availability.\"","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://www.stmarys-ca.edu/arts-sciences/nursing/admissions-aid/current-smc-student","https://www.stmarys-ca.edu/arts-sciences/nursing/admissions-aid/transfer-student","https://www.stmarys-ca.edu/arts-sciences/nursing/admissions-aid/first-year-student","https://www.stmarys-ca.edu/sites/default/files/2025-02/Handbook%20Associated%20Documents%20Nursing%202.11.2025.pdf"],"last_verified":"2026-11-25","academic_year":"Spring 2028 entry (Summer 2027 deadline has passed)","deadline":"Nov 1, 2026 (Summer 2027 entry) has passed; next: May 15, 2027 (Spring 2028 entry). Applications due \"no later than the term prior to beginning the Nursing Program.\"","notes":"Same prerequisite and GPA list on the current-student and transfer pages. First-year students enter through Public Health and apply to Nursing in fall of their second year, starting the program in fall of year three. Overall GPA is see_text because the page ties the 2.8 to prerequisite coursework, while the Feb 2025 handbook also lists 'Overall GPA: 2.8 (minimum)'. Handbook mentions a grading rubric for points that is not published. Progression: B- or higher in nursing courses; only one course may be repeated. Two letters of recommendation, resume; clinical readiness (health, background, drug checks) after acceptance."},
